import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.D2veAa-g.js";const m=JSON.parse('{"title":"SOA的参考架构","description":"","frontmatter":{"title":"SOA的参考架构"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/面向服务架构设计理论与实践（第二版）/SOA的作用/SOA的参考架构.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/面向服务架构设计理论与实践（第二版）/SOA的作用/SOA的参考架构.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/面向服务架构设计理论与实践（第二版）/SOA的作用/SOA的参考架构.md"};function r(e,l,n,c,u,d){return s(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="soa的参考架构" tabindex="-1">SOA的参考架构 <a class="header-anchor" href="#soa的参考架构" aria-label="Permalink to &quot;SOA的参考架构&quot;">​</a></h1><blockquote><p>共 11 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-服务组件体系结构-service-component-architecture-sca-是基于面向服务体系结构-service-oriented-architecture-soa-的思想描述服务之间组合和协作的规范。以下关于sca的叙述-不正确的是-。" tabindex="-1">Q1. 服务组件体系结构（Service Component Architecture，SCA）是基于面向服务体系结构（Service Oriented Architecture，SOA）的思想描述服务之间组合和协作的规范。以下关于SCA的叙述，不正确的是（ ）。 <a class="header-anchor" href="#q1-服务组件体系结构-service-component-architecture-sca-是基于面向服务体系结构-service-oriented-architecture-soa-的思想描述服务之间组合和协作的规范。以下关于sca的叙述-不正确的是-。" aria-label="Permalink to &quot;Q1. 服务组件体系结构（Service Component Architecture，SCA）是基于面向服务体系结构（Service Oriented Architecture，SOA）的思想描述服务之间组合和协作的规范。以下关于SCA的叙述，不正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> SCA定义了语言中立的服务组合方式，能够进行跨语言的服务调用</li><li><strong>B.</strong> SCA加强组件的接口与传输协议的关联，提高组件的内聚性</li><li><strong>C.</strong> SCA实现服务组件和其传输协议的绑定，这种绑定是可扩展的</li><li><strong>D.</strong> SCA主要是为了满足软件集成的需要而创建的架构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-是由中间件技术实现并支持soa的一组基础架构-它提供了一种基础设施-其优势在于-请作答此空" tabindex="-1">Q2. （ ）是由中间件技术实现并支持SOA的一组基础架构，它提供了一种基础设施，其优势在于（请作答此空） <a class="header-anchor" href="#q2-是由中间件技术实现并支持soa的一组基础架构-它提供了一种基础设施-其优势在于-请作答此空" aria-label="Permalink to &quot;Q2. （ ）是由中间件技术实现并支持SOA的一组基础架构，它提供了一种基础设施，其优势在于（请作答此空）&quot;">​</a></h2><ul><li><strong>A.</strong> 支持了服务请求者与服务提供者之间的直接链接</li><li><strong>B.</strong> 支持了服务请求者与服务提供者之间的紧密耦合</li><li><strong>C.</strong> 消除了服务请求者与服务提供者之间的直接链接</li><li><strong>D.</strong> 消除了服务请求者与服务提供者之间的关系</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q3-absdm-architecture-basedsoftwaredesignmodel-把整个基于体系结构软件过程划分为体系结构需求-体系结构设计-体系结构文档化、-请作答此空-和体系结构等6个子过程-其中-过程的主要输出结果是体系结构规格说明和测试体系结构需求的质量设计说明书。" tabindex="-1">Q3. ABSDM(Architecture-BasedSoftwareDesignModel)把整个基于体系结构软件过程划分为体系结构需求，体系结构设计，体系结构文档化、（请作答此空）和体系结构等6个子过程，其中（ ）过程的主要输出结果是体系结构规格说明和测试体系结构需求的质量设计说明书。 <a class="header-anchor" href="#q3-absdm-architecture-basedsoftwaredesignmodel-把整个基于体系结构软件过程划分为体系结构需求-体系结构设计-体系结构文档化、-请作答此空-和体系结构等6个子过程-其中-过程的主要输出结果是体系结构规格说明和测试体系结构需求的质量设计说明书。" aria-label="Permalink to &quot;Q3. ABSDM(Architecture-BasedSoftwareDesignModel)把整个基于体系结构软件过程划分为体系结构需求，体系结构设计，体系结构文档化、（请作答此空）和体系结构等6个子过程，其中（ ）过程的主要输出结果是体系结构规格说明和测试体系结构需求的质量设计说明书。&quot;">​</a></h2><ul><li><strong>A.</strong> 体系结构复审</li><li><strong>B.</strong> 体系结构测试</li><li><strong>C.</strong> 体系结构变更</li><li><strong>D.</strong> 体系结构管理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q4-soap-简单对象访问协议-是一种基于xml的轻量级协议-其核心组成部分不包括-。" tabindex="-1">Q4. SOAP（简单对象访问协议）是一种基于XML的轻量级协议，其核心组成部分不包括（）。 <a class="header-anchor" href="#q4-soap-简单对象访问协议-是一种基于xml的轻量级协议-其核心组成部分不包括-。" aria-label="Permalink to &quot;Q4. SOAP（简单对象访问协议）是一种基于XML的轻量级协议，其核心组成部分不包括（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 封装（Envelope）</li><li><strong>B.</strong> 编码规则</li><li><strong>C.</strong> 服务注册表</li><li><strong>D.</strong> 绑定（Binding）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q5-在web-service架构中-服务提供者的主要职责是-。" tabindex="-1">Q5. 在Web Service架构中，服务提供者的主要职责是（）。 <a class="header-anchor" href="#q5-在web-service架构中-服务提供者的主要职责是-。" aria-label="Permalink to &quot;Q5. 在Web Service架构中，服务提供者的主要职责是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 将服务描述发布到服务注册中心供其他服务查找和使用</li><li><strong>B.</strong> 为服务请求者和服务提供者之间提供交易平台</li><li><strong>C.</strong> 查找符合自身需求的服务并进行绑定调用</li><li><strong>D.</strong> 负责服务的底层传输协议和通信机制</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q6-在企业集成架构的6大类服务中-连接服务-connectivity-service-的主要作用是-。" tabindex="-1">Q6. 在企业集成架构的6大类服务中，连接服务（Connectivity Service）的主要作用是（）。 <a class="header-anchor" href="#q6-在企业集成架构的6大类服务中-连接服务-connectivity-service-的主要作用是-。" aria-label="Permalink to &quot;Q6. 在企业集成架构的6大类服务中，连接服务（Connectivity Service）的主要作用是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 提供业务系统运行的基础设施管理能力</li><li><strong>B.</strong> 通过企业服务总线提供分布在各种架构元素服务间的连接性</li><li><strong>C.</strong> 实现人、流程和信息集成的服务能力</li><li><strong>D.</strong> 监控业务系统运行时服务的业务性能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q7-在企业集成架构从服务为中心的视角划分中-负责提供分布在各种架构元素服务间连接性的是-。" tabindex="-1">Q7. 在企业集成架构从服务为中心的视角划分中，负责提供分布在各种架构元素服务间连接性的是（ ）。 <a class="header-anchor" href="#q7-在企业集成架构从服务为中心的视角划分中-负责提供分布在各种架构元素服务间连接性的是-。" aria-label="Permalink to &quot;Q7. 在企业集成架构从服务为中心的视角划分中，负责提供分布在各种架构元素服务间连接性的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> IT服务管理</li><li><strong>B.</strong> 业务逻辑服务</li><li><strong>C.</strong> 连接服务</li><li><strong>D.</strong> 控制服务</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q8-在业务流程分析的建立服务模型环节-自顶向下分解法的主要作用是-。" tabindex="-1">Q8. 在业务流程分析的建立服务模型环节，自顶向下分解法的主要作用是（ ）。 <a class="header-anchor" href="#q8-在业务流程分析的建立服务模型环节-自顶向下分解法的主要作用是-。" aria-label="Permalink to &quot;Q8. 在业务流程分析的建立服务模型环节，自顶向下分解法的主要作用是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 从业务视角对业务流程进行逐层分解至业务活动，明确各部分业务功能和逻辑</li><li><strong>B.</strong> 利用已有资产实现服务，对已有系统等进行分析挖掘服务候选者</li><li><strong>C.</strong> 把业务领域中易变和稳定部分分开，推导未来业务逻辑和潜在服务候选者</li><li><strong>D.</strong> 基于业务组件模型，将业务功能细化为具体操作步骤</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q9-在服务注册表中-以下哪项功能主要用于帮助服务使用者查询注册服务-寻找符合自身要求的服务-。" tabindex="-1">Q9. 在服务注册表中，以下哪项功能主要用于帮助服务使用者查询注册服务，寻找符合自身要求的服务 （ ）。 <a class="header-anchor" href="#q9-在服务注册表中-以下哪项功能主要用于帮助服务使用者查询注册服务-寻找符合自身要求的服务-。" aria-label="Permalink to &quot;Q9. 在服务注册表中，以下哪项功能主要用于帮助服务使用者查询注册服务，寻找符合自身要求的服务 （ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 服务注册</li><li><strong>B.</strong> 服务位置</li><li><strong>C.</strong> 服务绑定</li><li><strong>D.</strong> 服务发布</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q10-wsdl-web服务描述语言-用于描述web服务的三个基本属性-以下哪项不属于wsdl描述的基本属性-。" tabindex="-1">Q10. WSDL（Web服务描述语言）用于描述Web服务的三个基本属性，以下哪项不属于WSDL描述的基本属性（ ）。 <a class="header-anchor" href="#q10-wsdl-web服务描述语言-用于描述web服务的三个基本属性-以下哪项不属于wsdl描述的基本属性-。" aria-label="Permalink to &quot;Q10. WSDL（Web服务描述语言）用于描述Web服务的三个基本属性，以下哪项不属于WSDL描述的基本属性（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 服务功能</li><li><strong>B.</strong> 访问方式</li><li><strong>C.</strong> 服务位置</li><li><strong>D.</strong> 服务性能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q11-在web-service架构中-哪个组件负责提供服务查找和发布的平台功能-。" tabindex="-1">Q11. 在Web Service架构中，哪个组件负责提供服务查找和发布的平台功能（ ）。 <a class="header-anchor" href="#q11-在web-service架构中-哪个组件负责提供服务查找和发布的平台功能-。" aria-label="Permalink to &quot;Q11. 在Web Service架构中，哪个组件负责提供服务查找和发布的平台功能（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 服务提供者</li><li><strong>B.</strong> 服务注册中心</li><li><strong>C.</strong> 服务请求者</li><li><strong>D.</strong> 服务描述层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details>',35)])])}const h=t(i,[["render",r]]);export{m as __pageData,h as default};
